#!/usr/bin/env bash
# Fixes the progress bar's timing estimate for Stop/Restart/Configure so it
# stops lying about how long they take.
#
# Root cause: stop/restart/configure all go through
# ProcessSupervisor.stop() (agent/process_supervisor.py), which sends a
# graceful SIGTERM and then waits up to 10 REAL SECONDS before
# force-killing — intentional, so the kiosk app gets a fair chance to shut
# down cleanly instead of being killed abruptly. The progress bar was
# estimating "stop" at 4s, so it hit ~92% almost immediately and then sat
# there frozen for 6+ more seconds waiting on that real grace period —
# which is exactly what read as "stuck" / "taking so long". This does NOT
# shorten that 10s grace period (that's a real safety behavior, not a bug);
# it makes the UI's estimate honest about it instead, and adds a short
# hint under the bar explaining the wait so it reads as "in progress"
# rather than "broken" even when it does take the full 10s.
#
# Only app/templates/instances/detail.html changes in this push (the
# instances.py long-poll endpoint and the agent/commands.py immediate-
# heartbeat fix from the previous push are untouched and still in place).
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in app requirements.txt run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS"
cp app/templates/instances/detail.html "backups/$TS/detail.html.bak" 2>/dev/null || true
echo "==> Backed up existing file to backups/$TS/"

echo "==> Writing app/templates/instances/detail.html"
base64 -d > app/templates/instances/detail.html << 'DETAIL_HTML_B64'

DETAIL_HTML_B64

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
source venv/bin/activate
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "Done. Stopping a kiosk process will now show a bar that paces itself"
echo "over ~11s with a 'giving it a chance to shut down cleanly' hint,"
echo "instead of freezing at 92% for several seconds looking broken."
echo ""
echo "Reminder: this is still capped by the real 10s SIGTERM grace period"
echo "in agent/process_supervisor.py's stop(timeout=10.0). If you'd rather"
echo "Stop actually be faster (not just accurately displayed), that's a"
echo "one-line change to that timeout - say the word and I'll do that one"
echo "separately, since it trades off a clean shutdown window for speed."
